parameters.jsCode:
const seen = new Set();
const itemsOut = [];
for (const item of items) {
  const r = item.json;
  const email = (r.Email || r.email || '').toString().trim().toLowerCase();
  const ts = (r.Timestamp || r.timestamp || '').toString().trim();
  const key = `${email}__${ts}`;
  if (!email || !ts) continue;
  if (seen.has(key)) continue;
  seen.add(key);
  const urgencyRaw = (r['Nivel de urgencia'] || r.urgency || 'media').toString().trim().toLowerCase();
  const need = (r['¿Qué proceso quieres mejorar o automatizar?'] || r.need_summary || '').toString().trim();
  let score = 0;
  if (need.length > 20) score += 3;
  if ((r.Empresa || '').toString().trim()) score += 2;
  if (urgencyRaw === 'alta') score += 2;
  else if (urgencyRaw === 'media') score += 1;
  if ((r['Teléfono'] || r.phone || '').toString().trim()) score += 1;
  const createdAt = new Date(ts).toISOString();
  itemsOut.push({ json: {
    response_key: key,
    lead_id: `lead_${Date.now()}_${Math.floor(Math.random()*10000)}`,
    created_at: createdAt,
    source: 'google-form',
    campaign: '',
    name: (r['Nombre'] || r.name || '').toString().trim(),
    email,
    phone: (r['Teléfono'] || r.phone || '').toString().trim(),
    company: (r['Empresa'] || r.company || '').toString().trim(),
    role: (r['Cargo o rol'] || r.role || '').toString().trim(),
    need_summary: need,
    urgency: urgencyRaw || 'media',
    consent: (r['Consentimiento para contacto'] || r.consent || '').toString().trim(),
    status: 'nuevo',
    lead_score: score,
    owner: 'luis',
    first_response_at: '',
    meeting_booked_at: '',
    qualified_at: '',
    last_contact_at: createdAt,
    duplicate_of: '',
    notes: 'Captado desde Google Form y normalizado por n8n'
  } });
}
return itemsOut;

